import{_ as t,o,c as n,ag as a}from"./chunks/framework.Cyu1VozZ.js";const p=JSON.parse('{"title":"Collaboration & Sharing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/collaboration.md","filePath":"guide/collaboration.md"}'),r={name:"guide/collaboration.md"};function s(i,e,l,h,d,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="collaboration-sharing" tabindex="-1">Collaboration &amp; Sharing <a class="header-anchor" href="#collaboration-sharing" aria-label="Permalink to &quot;Collaboration &amp; Sharing&quot;">​</a></h1><p>Wafflebase lets multiple people edit the same sheet, document, presentation, or note at the same time — and read and comment on the same PDF. Share via link — no account required for recipients.</p><h2 id="share-a-document" tabindex="-1">Share a Document <a class="header-anchor" href="#share-a-document" aria-label="Permalink to &quot;Share a Document&quot;">​</a></h2><ol><li>Open the sheet or document you want to share</li><li>Click the <strong>Share</strong> button in the editor header</li><li>Under <strong>Permission</strong>, choose the role: <ul><li><strong>Viewer</strong> — Can see the content, but not edit</li><li><strong>Editor</strong> — Full editing access</li></ul></li><li>Under <strong>Expiration</strong>, choose <strong>No limit</strong>, <strong>1 hour</strong>, <strong>8 hours</strong>, <strong>24 hours</strong>, or <strong>7 days</strong></li><li>Click <strong>Create Link</strong> — the URL is created and copied to your clipboard</li></ol><p>Send the link to anyone. They can open it in their browser without signing in.</p><div class="warning custom-block"><p class="custom-block-title">Expiration defaults to No limit</p><p><strong>Expiration</strong> starts on <strong>No limit</strong>, so a link you create without touching that field never expires — it keeps working until you revoke it. Set a window before you click <strong>Create Link</strong> if the content is sensitive.</p></div><h3 id="who-can-create-an-editor-link" tabindex="-1">Who can create an editor link <a class="header-anchor" href="#who-can-create-an-editor-link" aria-label="Permalink to &quot;Who can create an editor link&quot;">​</a></h3><p><strong>Viewer</strong> links are open to any member of the document&#39;s workspace. <strong>Editor</strong> is restricted: only the document&#39;s author or an <strong>owner</strong> of its workspace can create one. Everyone else sees the Editor option greyed out with a note explaining why, and can create viewer links instead. The rule is enforced on the server, not just in the dialog.</p><h2 id="access-levels" tabindex="-1">Access Levels <a class="header-anchor" href="#access-levels" aria-label="Permalink to &quot;Access Levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Viewer</th><th>Editor</th></tr></thead><tbody><tr><td>View content</td><td>Yes</td><td>Yes</td></tr><tr><td>Navigate and scroll</td><td>Yes</td><td>Yes</td></tr><tr><td>Select and copy</td><td>Yes</td><td>Yes</td></tr><tr><td>Edit content</td><td>No</td><td>Yes</td></tr><tr><td>Format (cells or text)</td><td>No</td><td>Yes</td></tr><tr><td>Undo/redo</td><td>No</td><td>Yes</td></tr></tbody></table><p>In sheets, editors can also use formulas, insert/delete rows and columns, and resize columns. In docs, editors can apply text formatting and paragraph alignment.</p><h2 id="edit-together" tabindex="-1">Edit Together <a class="header-anchor" href="#edit-together" aria-label="Permalink to &quot;Edit Together&quot;">​</a></h2><p>When a collaborator opens your shared link, you&#39;ll see:</p><ul><li><strong>Their cursor</strong> — In sheets, a colored highlight on their selected cell. In docs and notes, a colored text cursor at their position. In PDFs, you can see who else is viewing the file.</li><li><strong>Their name</strong> — A label appears next to their cursor. In sheets and documents it fades about four seconds after they move so the content stays readable; hover their cursor to bring the name back. In notes, slides, and boards the label stays on screen and there is nothing to hover for.</li><li><strong>Live changes</strong> — Edits appear instantly with no need to refresh or save</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Each collaborator gets a unique color. If your collaborators sign in with GitHub, their name will appear next to their cursor.</p></div><h3 id="jump-to-a-collaborator" tabindex="-1">Jump to a collaborator <a class="header-anchor" href="#jump-to-a-collaborator" aria-label="Permalink to &quot;Jump to a collaborator&quot;">​</a></h3><p>In sheets and documents, the avatars in the header are clickable: select one to scroll to where that person is working. In documents, their name label reappears when you land so you can confirm whose position you jumped to; in sheets it does not, so if the label has already faded you&#39;ll see the colored cell highlight without a name until that person moves again. Your own avatar isn&#39;t clickable, and neither is one for a peer whose position isn&#39;t known yet.</p><h2 id="is-my-work-saved" tabindex="-1">Is My Work Saved? <a class="header-anchor" href="#is-my-work-saved" aria-label="Permalink to &quot;Is My Work Saved?&quot;">​</a></h2><p>A small status chip sits in the editor header and reports whether your edits have reached the server. It has four states:</p><table tabindex="0"><thead><tr><th>Chip</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Saved</strong></td><td>Connected, and everything you&#39;ve done is on the server.</td></tr><tr><td><strong>Saving…</strong></td><td>Connected, and your recent changes are on their way.</td></tr><tr><td><strong>Reconnecting…</strong></td><td>The connection dropped, but nothing of yours is waiting to be sent.</td></tr><tr><td><strong>Not saved</strong></td><td>You have changes that aren&#39;t reaching the server.</td></tr></tbody></table><p>Hover the chip for a fuller explanation of the current state. <strong>Not saved</strong> is the only state that is loud about itself: if it persists for a couple of seconds, a warning appears, and it clears with a confirmation once your work is actually on the server.</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t rely on the close prompt</p><p>While changes are unsent — that means <strong>Saving…</strong> as well as <strong>Not saved</strong> — this browser tab is the only copy of them; nothing is stored on your machine. In either of those two states, closing or reloading the tab <em>may</em> make the browser ask you to confirm first. It is a safety net, not a guarantee: the prompt appears only if a last-moment check still finds work outstanding, so a tab showing <strong>Not saved</strong> can close without asking. Never read a missing prompt as proof your work is safe — wait for <strong>Saved</strong> before leaving.</p></div><p>The chip appears in sheets, documents, slides, notes, and boards, and in a share link opened with the <strong>Editor</strong> role. A <strong>Viewer</strong> share link shows a <strong>View only</strong> badge in its place — a viewer makes no changes, so there is nothing for it to report.</p><h2 id="comments-mentions" tabindex="-1">Comments &amp; Mentions <a class="header-anchor" href="#comments-mentions" aria-label="Permalink to &quot;Comments &amp; Mentions&quot;">​</a></h2><p>Leave feedback without changing the content. Comments work on cells in sheets, on selected text in documents, and on a page region in PDFs. Slides, notes, and boards don&#39;t have comments yet.</p><h3 id="add-a-comment" tabindex="-1">Add a comment <a class="header-anchor" href="#add-a-comment" aria-label="Permalink to &quot;Add a comment&quot;">​</a></h3><p><strong>In a sheet:</strong></p><ol><li>Select the cell you want to comment on</li><li>Right-click and choose <strong>Insert comment</strong>, or press <strong>⌘+Option+M</strong> / <strong>Ctrl+Alt+M</strong></li><li>Type your comment and click <strong>Comment</strong></li></ol><p><strong>In a document:</strong></p><ol><li>Select the text you want to comment on — a document comment needs a real selection, so nothing happens if the cursor is just sitting somewhere</li><li>Right-click and choose <strong>Insert comment</strong>, or press <strong>⌘+Option+M</strong> / <strong>Ctrl+Alt+M</strong></li><li>Type your comment and click <strong>Comment</strong></li></ol><p>The comment icon in the header opens and closes the comments panel; it does not start a comment.</p><p>The commented text is highlighted so everyone can see where the discussion is.</p><p><strong>In a PDF:</strong></p><ol><li>Click <strong>Add comment</strong> in the header</li><li>Drag a rectangle over the region of the page you want to comment on</li><li>Type your comment and post it</li></ol><p>The comment is pinned to that page and region. Open the comments panel from the header to browse every thread by page. See <a href="/docs/pdf/viewing-pdfs.html">Viewing PDFs</a> for more.</p><h3 id="reply-resolve-edit" tabindex="-1">Reply, resolve, edit <a class="header-anchor" href="#reply-resolve-edit" aria-label="Permalink to &quot;Reply, resolve, edit&quot;">​</a></h3><ul><li><strong>Reply</strong> — Open a comment and click <strong>Reply</strong> to continue the thread.</li><li><strong>Resolve</strong> — Hover the thread and click the check (✓) to resolve it. Resolved threads are tucked away but never lost.</li><li><strong>Edit / Delete</strong> — Hover your own comment and use the <strong>⋯</strong> menu. Deleting the first comment removes the whole thread.</li></ul><h3 id="the-comments-panel" tabindex="-1">The comments panel <a class="header-anchor" href="#the-comments-panel" aria-label="Permalink to &quot;The comments panel&quot;">​</a></h3><p>Sheets and documents both have a side panel listing every thread. Click the comment icon in the header — or press <strong>⌘+Option+Shift+M</strong> / <strong>Ctrl+Alt+Shift+M</strong> — to open it. Threads are grouped under <strong>Open</strong> and <strong>Resolved</strong> tabs; click a thread to jump to the cell or text it belongs to. In a document, if the text a comment was attached to is later deleted, the thread moves to an orphaned list so the conversation is preserved.</p><p>PDFs have a comments panel too, opened from the header — see <a href="/docs/pdf/viewing-pdfs.html">Viewing PDFs</a>.</p><h3 id="mention-a-teammate" tabindex="-1">Mention a teammate <a class="header-anchor" href="#mention-a-teammate" aria-label="Permalink to &quot;Mention a teammate&quot;">​</a></h3><p>Type <strong>@</strong> inside a comment to mention a workspace member. An autocomplete list appears — keep typing to filter, then use <strong>↑ / ↓</strong> and <strong>Enter</strong> (or <strong>Tab</strong>) to pick someone. The mention is inserted as a blue chip so it stands out in the thread.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Mentions highlight who a comment is for. Only people who are members of the workspace can be mentioned.</p></div><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>A mention doesn&#39;t just stand out in the thread — it reaches the person. The bell in the header carries a badge with your unread count (it stops counting at <strong>99+</strong>), and opening it lists what happened, newest first. Select a row to mark it read and jump to what it&#39;s about, or use <strong>Mark all read</strong> to clear the badge.</p><p>You are notified when:</p><ul><li><strong>Someone mentions you</strong> in a comment</li><li><strong>Someone replies</strong> to a thread you&#39;ve commented in</li><li><strong>Someone resolves</strong> a thread you&#39;ve commented in</li><li><strong>Someone joins a workspace</strong> you own, or accepts an invite you created</li><li><strong>A template you published</strong> is approved, rejected, or removed from the public gallery, or goes back for review after its document changed</li><li><strong>A template is waiting in the review queue</strong> — only if you are one of the deployment&#39;s designated template reviewers, and at most one nudge per listing per day</li></ul><p>Starting a brand-new thread notifies nobody unless it mentions someone. You are never notified about your own actions, and a reply that mentions you produces one notification, not two.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The bell only appears when you&#39;re signed in — someone reading through a share link has no inbox. Notifications also stay inside the workspace: only workspace members can be notified, and only a workspace member&#39;s comment can notify anyone.</p></div><h2 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h2><p>Every sheet, document, presentation, note, and board keeps a history of past versions. The <strong>history</strong> icon in the editor header opens the panel; each entry can be previewed read-only or restored, and a restore is itself reversible.</p><p>Two things about it matter when other people are in the document with you:</p><ul><li><strong>Comments are part of the version being restored.</strong> Restoring an older version removes every comment added after it, along with the rest of the newer content.</li><li><strong>History is signed-in only.</strong> It is not part of a share link, so a collaborator working through a shared URL has no panel and cannot restore.</li></ul><p>The full treatment — naming a version, what a preview shows for each document type, what a restore replaces, and the limits — is in <a href="/docs/guide/version-history.html">Version History</a>.</p><h2 id="how-conflicts-work" tabindex="-1">How Conflicts Work <a class="header-anchor" href="#how-conflicts-work" aria-label="Permalink to &quot;How Conflicts Work&quot;">​</a></h2><p>What happens if two people edit the same cell or text at the same time?</p><p>Wafflebase uses CRDTs (Conflict-free Replicated Data Types) to handle this. Both edits are preserved in the system — the last writer&#39;s value is displayed in sheets, and concurrent text insertions are merged in docs. There&#39;s no &quot;conflict dialog&quot; or manual merge step.</p><p>In practice, presence cursors make it easy to see where others are working, so simultaneous edits to the same location are rare.</p><h2 id="manage-share-links" tabindex="-1">Manage Share Links <a class="header-anchor" href="#manage-share-links" aria-label="Permalink to &quot;Manage Share Links&quot;">​</a></h2><p>To see or revoke existing links:</p><ol><li>Open the sheet or document</li><li>Click <strong>Share</strong> in the editor header</li><li>Under <strong>Active links</strong> you&#39;ll see each link&#39;s role and expiration — <strong>No expiration</strong>, a countdown such as <em>Expires in 6h</em>, or <strong>Expired</strong></li><li>Use the copy icon to copy a link again, or the delete icon to revoke it. The delete icon only appears on links you have the authority to revoke — see below</li></ol><p>Revoking a link immediately blocks access — anyone with that URL will no longer be able to open it.</p><p>You can always revoke a link you created yourself. Revoking links other people created takes the same authority as creating an editor link: the document&#39;s author or a workspace owner. Editor links you didn&#39;t create aren&#39;t listed for you at all, so the token can&#39;t be copied and passed on.</p><h2 id="good-to-know" tabindex="-1">Good to Know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to Know&quot;">​</a></h2><ul><li>Revoking or expiring a link blocks access immediately</li><li>Deleting a document automatically invalidates all its share links</li><li>Links cannot be guessed — each one is generated with a unique random ID</li><li>New links are created with <strong>No limit</strong> unless you pick an expiration, so for sensitive data choose a short one (1 hour or 8 hours) before creating the link</li></ul><h2 id="tips-for-collaboration" tabindex="-1">Tips for Collaboration <a class="header-anchor" href="#tips-for-collaboration" aria-label="Permalink to &quot;Tips for Collaboration&quot;">​</a></h2><ul><li><strong>Use clear names</strong> — Title your sheets and documents descriptively so teammates can find them</li><li><strong>Communicate changes</strong> — If you restructure columns or reorganize content, let your team know</li><li><strong>Use separate tabs</strong> (sheets) — Give each team member their own tab for data entry, with a summary tab that pulls data using formulas</li></ul>',67)])])}const g=t(r,[["render",s]]);export{p as __pageData,g as default};
